import ReactPlayer from "react-player/lazy";
import Func_AutoScrollThumbnails from "../KoorFunction/Func_YT-ThumbnailScroll";
import { FaYoutube } from "react-icons/fa6";

{
  /* Note: Change Youtube Thumbnail IDs in Func_AutoScrollThumbnails*/
}

function Main_Youtube() {
  return (
    <div
      id="video"
      className="bg-[#ffb600] max-w-screen-xl grid grid-cols-1 lg:grid-cols-2 items-center w-full
      bg-[url('../public/assets/bg_box/pexels-liser1227-11521734.webp')] max-w-screen-xl w-full bg-cover bg-top bg-no-repeat"
    >
      <div className="rounded-xl border-4 border-white my-3 mx-3 lg:mr-0 overflow-hidden lg:col-span-1 aspect-video">
        <ReactPlayer
          url="https://www.youtube.com/watch?v=saXzXq3lXnM"
          width="100%"
          height="100%"
          config={{
            youtube: {
              playerVars: { controls: 1 },
              embedOptions: {
                host: 'https://www.youtube-nocookie.com'
              }
            }
          }}
        />
      </div>

      <div className="grid grid-cols-1 grid-rows-2 gap-1 w-full">
        <a
          href="https://www.youtube.com/@PureKoor"
          target="_blank"
          rel="noopener noreferrer"
          className="border-4 bg-red-600 hover:bg-red-700 rounded-xl flex w-3/4 aspect-[4/1] m-auto transition-all hover:scale-90 hover:border-[#ff0000] duration-450 ease-in-out [container-type:inline-size]"
        >
          <p className="text-[clamp(1.875rem,13cqi,3.75rem)] m-auto font-bold align-middle text-white align-right flex items-center">
            <FaYoutube className="mr-3" />
            Subscribe!
          </p>
        </a>
        <Func_AutoScrollThumbnails />
      </div>
    </div>
  );
}

export default Main_Youtube;
